    positions: ['Р СѓРєРѕРІРѕРґРёС‚РµР»СЊ РѕС‚РґРµР»Р° РїСЂРѕРґР°Р¶', 'HR BP', 'C&B РђРЅР°Р»РёС‚РёРє', 'Р‘СѓС…РіР°Р»С‚РµСЂ', 'РРЅР¶РµРЅРµСЂ-С‚РµС…РЅРѕР»РѕРі', 'Р®СЂРёСЃС‚', 'Р›РѕРіРёСЃС‚', 'Р’РѕРґРёС‚РµР»СЊ'],
